  2	 * @file main.c
  3	 * @brief Chương trình chính STM32F469I-DISCO với 6 tác vụ trên nhân RTOS tiền định
  4	 *        chuyển đổi từ tham-khao/main-freertos.c:
  5	 *        1. vTaskLED1
  6	 *        2. vTaskLED2
  7	 *        3. vTaskButton (quét nút USER PA0)
  8	 *        4. vTaskLED3 (chờ hàng đợi từ nút bấm)
  9	 *        5. vTaskMonitor (nhịp tim LED4 PK3)
 10	 *        6. vTaskLCD (quản lý LCD DSI OTM8009A, cảm ứng FT6206)
 11	 */
