 21	/* Định nghĩa chân LED trên STM32F469I-DISCO (Active LOW) */
 22	/* LED1: PG6, LED2: PD4, LED3: PD5, LED4: PK3 */
 23	#define LED1_PIN              (6UL)
 24	#define LED2_PIN              (4UL)
 25	#define LED3_PIN              (5UL)
 26	#define LED4_PIN              (3UL)
 27	
 28	/* Định nghĩa chân nút bấm USER (Active HIGH) - WAKEUP: PA0 */
 29	#define BUTTON_PIN            (0UL)
 30	
 31	/* Dung lượng hàng đợi sự kiện */
 32	#define QUEUE_CAPACITY        4U
 33	
 34	/* Hàng đợi truyền tín hiệu sự kiện từ nút bấm PA0 sang tác vụ LED3 và LCD */
 35	static uint32_t button_queue_storage[QUEUE_CAPACITY];
 36	static rtos_queue_t xButtonQueue;
 37	
 38	static uint32_t ui_queue_storage[QUEUE_CAPACITY];
 39	static rtos_queue_t xUIQueue;
