202	/* Task 5: Quản lý hiển thị LCD DSI OTM8009A và cập nhật giao diện */
203	static void vTaskLCD(void *pvParameters)
204	{
205	    (void)pvParameters;
206	    uint32_t rx_msg = 0;
207	
208	    /* Khởi tạo SDRAM và màn hình LCD DSI */
